SELECT id, subject_table, subject_id, field_path, claim_text, source_id, citation, note, status FROM jsonb_populate_recordset(NULL::public.fact_claim, '[{"subject_table": "event", "field_path": "description", "claim_text": "柴荣撤销镇国军建制。", "citation": "卷292·显德元年（954年八月至十一月及相关追述）·zztj-v292-y0954-p014·原文件第19行", "note": "原文：己巳，废镇国军。；核对说明：撤销军额不等于毁掉城池或杀尽军人；《旧五代史》本纪补依旧为郡。", "status": "draft", "id": "df946fb0-d363-51f5-a930-4feb6e634c17", "subject_id": "95184859-bfc6-596b-823e-5e722e90c27f", "source_id": "a66d5cae-8694-531b-89b0-6d7bdf64fef7"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "954年八月己巳", "citation": "卷292·显德元年（954年八月至十一月及相关追述）·zztj-v292-y0954-p014·原文件第19行", "note": "原文：己巳，废镇国军。；核对说明：按《资治通鉴》及对应补证纪时；追叙或他书记载另作说明，不自行换算公历日期。", "status": "draft", "id": "97727e1a-b334-5d3f-a82c-5e279fa2e214", "subject_id": "95184859-bfc6-596b-823e-5e722e90c27f", "source_id": "a66d5cae-8694-531b-89b0-6d7bdf64fef7"}, {"subject_table": "person", "field_path": "description", "claim_text": "柴荣：撤销镇国军建制。", "citation": "卷292·显德元年（954年八月至十一月及相关追述）·zztj-v292-y0954-p014·原文件第19行", "note": "原文：己巳，废镇国军。；核对说明：核对同名、职务及行动后识别主体；展示简体，摘录保留原字。", "status": "draft", "id": "c80159c7-5d28-5e6c-ab51-5e7dadbd9364", "subject_id": "697c1a4f-b373-5a78-8b47-330fe349a424", "source_id": "a66d5cae-8694-531b-89b0-6d7bdf64fef7"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "柴荣：撤销镇国军建制。", "citation": "卷292·显德元年（954年八月至十一月及相关追述）·zztj-v292-y0954-p014·原文件第19行", "note": "原文：己巳，废镇国军。；核对说明：参与身份依据本句；人名沿用已有主体，原文不改字。", "status": "draft", "id": "8d33e294-035f-5c90-8cd9-0bc616e622ef", "subject_id": "e31fe38c-9e11-582b-99d7-64458830cf1a", "source_id": "a66d5cae-8694-531b-89b0-6d7bdf64fef7"}, {"subject_table": "event", "field_path": "description", "claim_text": "《旧五代史》同记八月己巳停华州镇国军、依旧为郡。", "citation": "《旧五代史》卷一百十四，段落 jiu-wudaishi-205deb4a7860-p002713；EPUB电子本，纸本及异文待核", "note": "原文：己巳，宜停華州鎮國軍，依舊為郡。；核对说明：补所在地与撤销军额后的行政表述，不推全城废弃。", "status": "draft", "id": "621c3974-2e06-514e-856a-3fd58014